/**
 * Health Economics teaching boards.
 * White background, primary #9333ea (matches generate-guidebook-figures.js).
 * QALY figure is generated by generate-he-qaly-figure.py (Drummond Fig 5.2).
 */
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const { createCanvas } = require("canvas");

const OUTPUT_DIR = path.join(__dirname, "..", "reading-illustrations");
const PRIMARY = "#9333ea";
const PRIMARY_SOFT = "#F3E8FF";
const PRIMARY_MID = "#C084FC";
const PRIMARY_DARK = "#7C3AED";
const INK = "#1F2937";
const MUTED = "#6B7280";
const GRID = "#E5E7EB";
const WHITE = "#FFFFFF";
const BODY = "#374151";

const ensureDir = () => {
  if (!fs.existsSync(OUTPUT_DIR)) fs.mkdirSync(OUTPUT_DIR, { recursive: true });
};

const roundRect = (ctx, x, y, w, h, r, fill, stroke, lineWidth = 2) => {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
  if (fill) {
    ctx.fillStyle = fill;
    ctx.fill();
  }
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }
};

const wrapText = (ctx, text, x, y, maxWidth, lineHeight, font, color, maxLines = 6) => {
  ctx.font = font;
  ctx.fillStyle = color;
  const words = String(text).split(" ");
  let line = "";
  let currentY = y;
  let used = 0;
  for (const word of words) {
    const next = `${line}${word} `;
    if (ctx.measureText(next).width > maxWidth && line) {
      ctx.fillText(line.trim(), x, currentY);
      currentY += lineHeight;
      used += 1;
      line = `${word} `;
      if (used >= maxLines) return currentY;
    } else {
      line = next;
    }
  }
  if (line.trim()) {
    ctx.fillText(line.trim(), x, currentY);
    currentY += lineHeight;
  }
  return currentY;
};

const write = (fileName, painter, width = 1400, height = 1400) => {
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = WHITE;
  ctx.fillRect(0, 0, width, height);
  painter(ctx, width, height);
  const out = path.join(OUTPUT_DIR, fileName);
  fs.writeFileSync(out, canvas.toBuffer("image/png"));
  console.log("wrote", out);
};

const drawTitle = (ctx, title, subtitle) => {
  ctx.fillStyle = INK;
  ctx.font = "700 40px Sans";
  ctx.fillText(title, 64, 72);
  ctx.fillStyle = MUTED;
  ctx.font = "24px Sans";
  ctx.fillText(subtitle, 64, 110);
  ctx.fillStyle = PRIMARY;
  ctx.fillRect(64, 128, 180, 5);
};

const comparative = (ctx) => {
  drawTitle(ctx, "Comparative analysis", "A full evaluation always compares alternatives");

  const drawRow = (y, leftLabel, midLabel, rightLabel, accent) => {
    roundRect(ctx, 80, y, 340, 140, 16, WHITE, accent, 2);
    ctx.fillStyle = INK;
    ctx.font = "700 26px Sans";
    ctx.textAlign = "center";
    ctx.fillText(leftLabel, 250, y + 82);

    ctx.fillStyle = accent;
    ctx.beginPath();
    ctx.moveTo(440, y + 70);
    ctx.lineTo(490, y + 70);
    ctx.lineTo(478, y + 58);
    ctx.moveTo(490, y + 70);
    ctx.lineTo(478, y + 82);
    ctx.strokeStyle = accent;
    ctx.lineWidth = 3;
    ctx.stroke();

    roundRect(ctx, 510, y, 380, 140, 16, PRIMARY_SOFT, PRIMARY, 2);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 26px Sans";
    ctx.fillText(midLabel, 700, y + 82);

    ctx.beginPath();
    ctx.moveTo(910, y + 70);
    ctx.lineTo(960, y + 70);
    ctx.lineTo(948, y + 58);
    ctx.moveTo(960, y + 70);
    ctx.lineTo(948, y + 82);
    ctx.stroke();

    roundRect(ctx, 980, y, 340, 140, 16, WHITE, accent, 2);
    ctx.fillStyle = INK;
    ctx.font = "700 26px Sans";
    ctx.fillText(rightLabel, 1150, y + 82);
    ctx.textAlign = "left";
  };

  ctx.fillStyle = MUTED;
  ctx.font = "700 22px Sans";
  ctx.fillText("CHOICE", 80, 210);

  drawRow(250, "COSTS A", "Programme A", "CONSEQUENCES A", PRIMARY);
  drawRow(520, "COSTS B", "Comparator B", "CONSEQUENCES B", PRIMARY_DARK);

  wrapText(
    ctx,
    "Programme A is the option of interest. Comparator B may be current practice, a low-cost option, or doing nothing. Compare the difference in costs with the difference in consequences.",
    80,
    740,
    1240,
    36,
    "24px Sans",
    BODY,
    4
  );
  wrapText(
    ctx,
    "Incremental rule: (costs A minus costs B) versus (consequences A minus consequences B). Cost-of-illness studies are not full evaluations.",
    80,
    900,
    1240,
    36,
    "24px Sans",
    BODY,
    3
  );
};

const types = (ctx) => {
  drawTitle(ctx, "Types of economic evaluation", "Consequences decide the method");
  const rows = [
    { t: "Cost analysis", d: "Money costs only. No comparison of consequences. Not a full evaluation." },
    { t: "CMA", d: "Costs in money. Effects treated as equivalent. Not a design to declare in advance." },
    { t: "CEA", d: "Costs in money. One shared effect in natural units (life-years, cases, mmHg)." },
    { t: "CUA", d: "Costs in money. Generic health, usually QALY. Compares across diseases." },
    { t: "CBA", d: "Costs and consequences both in money (willingness to pay)." },
    { t: "CCA", d: "Costs plus several effects left in natural units. Decision-maker supplies weights." },
  ];
  rows.forEach((r, i) => {
    const y = 180 + i * 195;
    roundRect(ctx, 70, y, 1260, 175, 16, WHITE, GRID, 1);
    roundRect(ctx, 70, y, 14, 175, 0, PRIMARY);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 28px Sans";
    ctx.fillText(r.t, 110, y + 55);
    wrapText(ctx, r.d, 110, y + 100, 1180, 34, "24px Sans", BODY, 2);
  });
};

const costTaxonomy = (ctx) => {
  drawTitle(ctx, "Cost taxonomy", "Identify, then measure, then value");
  roundRect(ctx, 70, 180, 610, 520, 18, WHITE, GRID, 1);
  roundRect(ctx, 70, 180, 610, 72, 18, PRIMARY);
  ctx.fillStyle = WHITE;
  ctx.font = "700 28px Sans";
  ctx.fillText("Provider (facility)", 100, 226);
  [
    ["Capital", "Land, building, equipment, vehicle"],
    ["Recurrent", "Staff, electricity, fuel, supplies"],
  ].forEach((item, i) => {
    const y = 280 + i * 190;
    roundRect(ctx, 110, y, 530, 160, 14, PRIMARY_SOFT, PRIMARY, 1.5);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 26px Sans";
    ctx.fillText(item[0], 140, y + 55);
    wrapText(ctx, item[1], 140, y + 100, 470, 32, "22px Sans", BODY, 2);
  });

  roundRect(ctx, 720, 180, 610, 520, 18, WHITE, GRID, 1);
  roundRect(ctx, 720, 180, 610, 72, 18, PRIMARY_DARK);
  ctx.fillStyle = WHITE;
  ctx.font = "700 28px Sans";
  ctx.fillText("Purchaser (patient / payer)", 750, 226);
  [
    ["Direct OOPE", "Medicines, tests, fees, travel"],
    ["Indirect / time", "Lost work time and caregiver time"],
  ].forEach((item, i) => {
    const y = 280 + i * 190;
    roundRect(ctx, 760, y, 530, 160, 14, PRIMARY_SOFT, PRIMARY_DARK, 1.5);
    ctx.fillStyle = PRIMARY_DARK;
    ctx.font = "700 26px Sans";
    ctx.fillText(item[0], 790, y + 55);
    wrapText(ctx, item[1], 790, y + 100, 470, 32, "22px Sans", BODY, 2);
  });

  wrapText(
    ctx,
    "Also count other public sectors when relevant. Do not double-count OOPE as both a facility receipt and a household cost in the same total. Marginal cost = extra cost of one more unit.",
    70,
    740,
    1260,
    36,
    "24px Sans",
    BODY,
    4
  );
  roundRect(ctx, 70, 940, 1260, 280, 18, PRIMARY_SOFT, PRIMARY, 2);
  wrapText(
    ctx,
    "Four buckets for a long answer: (1) health sector  (2) patient and family  (3) other sectors  (4) productivity, with a double-counting warning if QALYs already value being able to work.",
    110,
    1020,
    1180,
    40,
    "26px Sans",
    INK,
    5
  );
};

const discounting = (ctx) => {
  drawTitle(ctx, "Discounting", "Future amounts as present values");
  roundRect(ctx, 80, 180, 1240, 260, 18, WHITE, PRIMARY, 2);
  ctx.fillStyle = INK;
  ctx.font = "700 34px Sans";
  ctx.fillText("Present value  =  future amount  x  1 / (1 + r)^n", 120, 290);
  wrapText(ctx, "r = annual discount rate     n = years until the cost or effect occurs", 120, 350, 1160, 36, "24px Sans", BODY, 2);

  const cards = [
    { t: "Why", d: "Time preference: resources now can be used in the interim. Delayed programmes must not win only because their bills look later." },
    { t: "Direction", d: "Higher r or larger n lowers present value. Equal rates for costs and health effects unless the question states an exception." },
    { t: "Practice", d: "State the rate (often 3% or 5% in published studies), discount both sides, and test other rates in sensitivity analysis." },
  ];
  cards.forEach((c, i) => {
    const y = 480 + i * 280;
    roundRect(ctx, 80, y, 1240, 250, 16, i % 2 === 0 ? PRIMARY_SOFT : WHITE, GRID, 1);
    roundRect(ctx, 80, y, 14, 250, 0, PRIMARY);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 28px Sans";
    ctx.fillText(c.t, 120, y + 60);
    wrapText(ctx, c.d, 120, y + 110, 1160, 36, "24px Sans", BODY, 3);
  });
};

const cePlane = (ctx) => {
  drawTitle(ctx, "Cost-effectiveness plane", "Extra cost against extra effect");
  const cx = 700;
  const cy = 780;
  const arm = 420;
  ctx.strokeStyle = INK;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(cx - arm, cy);
  ctx.lineTo(cx + arm, cy);
  ctx.moveTo(cx, cy + arm);
  ctx.lineTo(cx, cy - arm);
  ctx.stroke();

  ctx.fillStyle = INK;
  ctx.font = "22px Sans";
  ctx.textAlign = "center";
  ctx.fillText("Extra effect", cx + arm - 20, cy + 36);
  ctx.save();
  ctx.translate(cx - 36, cy - arm + 10);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText("Extra cost", 0, 0);
  ctx.restore();
  ctx.textAlign = "left";

  ctx.setLineDash([10, 8]);
  ctx.strokeStyle = PRIMARY;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(cx - 300, cy + 185);
  ctx.lineTo(cx + 300, cy - 185);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = PRIMARY;
  ctx.font = "700 20px Sans";
  ctx.fillText("k (threshold)", cx + 250, cy - 210);

  const qs = [
    { x: cx + 90, y: cy - 360, t: "I  more health, more cost", d: "Use threshold k" },
    { x: cx + 90, y: cy + 140, t: "II  more health, less cost", d: "Accept (dominant)" },
    { x: cx - 440, y: cy + 140, t: "III  less health, less cost", d: "Use threshold k" },
    { x: cx - 440, y: cy - 360, t: "IV  less health, more cost", d: "Reject (dominated)" },
  ];
  qs.forEach((q) => {
    roundRect(ctx, q.x, q.y, 350, 130, 12, PRIMARY_SOFT, PRIMARY, 1.5);
    ctx.fillStyle = INK;
    ctx.font = "700 18px Sans";
    wrapText(ctx, q.t, q.x + 18, q.y + 42, 314, 24, "700 18px Sans", INK, 2);
    wrapText(ctx, q.d, q.x + 18, q.y + 92, 314, 24, "18px Sans", BODY, 1);
  });
  ctx.fillStyle = PRIMARY;
  ctx.beginPath();
  ctx.arc(cx, cy, 8, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = INK;
  ctx.font = "18px Sans";
  ctx.fillText("Comparator", cx + 16, cy - 14);
};

const icerBoard = (ctx) => {
  drawTitle(ctx, "ICER", "Extra cost per extra unit of effect");
  roundRect(ctx, 80, 180, 1240, 320, 18, WHITE, PRIMARY, 2);
  ctx.fillStyle = INK;
  ctx.font = "700 38px Sans";
  ctx.fillText("ICER  =  (C1 - C0)  /  (E1 - E0)", 160, 320);
  wrapText(ctx, "C1, E1 = new option     C0, E0 = comparator     Effect may be life-years, cases, or QALYs", 160, 390, 1080, 36, "24px Sans", BODY, 3);

  const bits = [
    { t: "Always incremental", d: "Do not divide cost of A by effect of A if current practice already costs money and produces health." },
    { t: "NMB = E k - C", d: "Linear rule at threshold k. Choose the option with the highest net monetary benefit." },
    { t: "NHB = E - C/k", d: "The same rule in health units. Useful when extra effect is small or negative." },
    { t: "India", d: "No single statutory rupee-per-QALY law. HTAIn and districts still use extra cost versus extra effect." },
  ];
  bits.forEach((b, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 80 + col * 640;
    const y = 540 + row * 380;
    roundRect(ctx, x, y, 600, 350, 16, WHITE, GRID, 1);
    roundRect(ctx, x, y, 14, 350, 0, PRIMARY);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 26px Sans";
    ctx.fillText(b.t, x + 44, y + 60);
    wrapText(ctx, b.d, x + 44, y + 120, 520, 34, "24px Sans", BODY, 5);
  });
};

const decisionTree = (ctx, width, height) => {
  drawTitle(ctx, "Decision tree", "Squares choose. Circles chance. Terminals score.");

  const line = (x1, y1, x2, y2) => {
    ctx.strokeStyle = INK;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  };
  const square = (x, y, s, label) => {
    roundRect(ctx, x - s / 2, y - s / 2, s, s, 6, PRIMARY_SOFT, PRIMARY, 2);
    ctx.fillStyle = INK;
    ctx.font = "700 18px Sans";
    ctx.textAlign = "center";
    ctx.fillText(label, x, y + 6);
    ctx.textAlign = "left";
  };
  const circle = (x, y, r) => {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = WHITE;
    ctx.fill();
    ctx.strokeStyle = PRIMARY;
    ctx.lineWidth = 2.4;
    ctx.stroke();
  };
  const terminal = (x, y, w, h, title, sub) => {
    roundRect(ctx, x, y - h / 2, w, h, 10, WHITE, PRIMARY, 1.8);
    ctx.fillStyle = INK;
    ctx.font = "700 18px Sans";
    ctx.fillText(title, x + 16, y - 6);
    ctx.fillStyle = MUTED;
    ctx.font = "16px Sans";
    ctx.fillText(sub, x + 16, y + 18);
  };
  const branchLabel = (x, y, text) => {
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 16px Sans";
    ctx.fillText(text, x, y);
  };

  const dx = 140;
  const dy = 520;
  square(dx, dy, 92, "Decision");

  const chemoY = 300;
  const noneY = 760;
  const optX = 430;
  line(dx + 46, dy, optX - 110, chemoY);
  line(dx + 46, dy, optX - 110, noneY);
  roundRect(ctx, optX - 110, chemoY - 28, 220, 56, 10, WHITE, PRIMARY, 2);
  roundRect(ctx, optX - 110, noneY - 28, 220, 56, 10, WHITE, PRIMARY_DARK, 2);
  ctx.fillStyle = INK;
  ctx.font = "700 22px Sans";
  ctx.textAlign = "center";
  ctx.fillText("Chemotherapy", optX, chemoY + 8);
  ctx.fillText("No chemotherapy", optX, noneY + 8);
  ctx.textAlign = "left";

  const chanceX = 720;
  circle(chanceX, chemoY, 22);
  circle(chanceX, noneY, 22);
  line(optX + 110, chemoY, chanceX - 22, chemoY);
  line(optX + 110, noneY, chanceX - 22, noneY);

  const termX = 980;
  const termW = 340;
  const chemoTerms = [
    { y: 210, p: "Fever / neutropenia  p1", title: "Hospital", sub: "Cost and effect of this path" },
    { y: 390, p: "No fever  1 - p1", title: "Home / no extra Rx", sub: "Cost and effect of this path" },
  ];
  chemoTerms.forEach((row) => {
    line(chanceX + 22, chemoY, termX, row.y);
    branchLabel(chanceX + 36, row.y < chemoY ? row.y - 14 : row.y + 28, row.p);
    terminal(termX, row.y, termW, 70, row.title, row.sub);
  });

  const noneTerms = [
    { y: 670, p: "Disease fever  p2", title: "Hospital", sub: "Cost and effect of this path" },
    { y: 850, p: "No fever  1 - p2", title: "Home / no extra Rx", sub: "Cost and effect of this path" },
  ];
  noneTerms.forEach((row) => {
    line(chanceX + 22, noneY, termX, row.y);
    branchLabel(chanceX + 36, row.y < noneY ? row.y - 14 : row.y + 28, row.p);
    terminal(termX, row.y, termW, 70, row.title, row.sub);
  });

  const legendY = 980;
  square(90, legendY, 28, "");
  ctx.fillStyle = BODY;
  ctx.font = "18px Sans";
  ctx.fillText("Decision node", 112, legendY + 6);
  circle(340, legendY, 12);
  ctx.fillStyle = BODY;
  ctx.fillText("Chance node", 362, legendY + 6);
  roundRect(ctx, 560, legendY - 14, 28, 28, 6, WHITE, PRIMARY, 1.6);
  ctx.fillStyle = BODY;
  ctx.fillText("Terminal (cost, effect)", 600, legendY + 6);

  wrapText(
    ctx,
    "Expected cost = sum (path probability x path cost). Same for effect. Then compare incrementally. Use a Markov model when events repeat over many cycles.",
    70,
    1060,
    width - 140,
    34,
    "22px Sans",
    BODY,
    3
  );
};

const financing = (ctx) => {
  drawTitle(ctx, "Health financing in India", "NHA 2022-23: who pays");
  const streams = [
    { t: "1. Government", d: "Union and States. Tax-funded services, NHM, programmes. NHP-2017 goal: GHE toward 2.5% of GDP by 2025. NHA 2022-23: GHE 1.48% of GDP, 43.7% of THE." },
    { t: "2. Households (OOPE)", d: "Direct payment at the point of care, not pooled. NHA 2022-23: 43.4% of THE (from 64.2% in 2013-14)." },
    { t: "3. Insurance / social security", d: "AB-PMJAY, ESI, CGHS, state schemes, private insurance. Pooling is the point: many pay, the sick draw." },
    { t: "4. Partners", d: "External agencies, NGOs, CSR. Useful at the margin. Not the backbone of universal cover." },
  ];
  streams.forEach((s, i) => {
    const y = 180 + i * 280;
    roundRect(ctx, 70, y, 1260, 250, 16, WHITE, GRID, 1);
    roundRect(ctx, 70, y, 14, 250, 0, PRIMARY);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 28px Sans";
    ctx.fillText(s.t, 110, y + 55);
    wrapText(ctx, s.d, 110, y + 105, 1180, 34, "24px Sans", BODY, 3);
  });
};

const uhcCube = (ctx) => {
  drawTitle(ctx, "UHC cube", "Population, services, cost share");
  const drawCube = (x, y, s, fill, stroke) => {
    ctx.fillStyle = fill;
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.rect(x, y, s, s);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + s * 0.4, y - s * 0.28);
    ctx.lineTo(x + s + s * 0.4, y - s * 0.28);
    ctx.lineTo(x + s, y);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x + s, y);
    ctx.lineTo(x + s + s * 0.4, y - s * 0.28);
    ctx.lineTo(x + s + s * 0.4, y + s - s * 0.28);
    ctx.lineTo(x + s, y + s);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.globalAlpha = 0.7;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.stroke();
  };
  drawCube(160, 500, 400, PRIMARY_SOFT, PRIMARY);
  drawCube(250, 610, 210, PRIMARY, PRIMARY_DARK);
  ctx.fillStyle = INK;
  ctx.font = "700 22px Sans";
  ctx.fillText("Desired system", 160, 960);
  ctx.fillStyle = WHITE;
  ctx.font = "700 22px Sans";
  ctx.fillText("Today", 295, 730);

  const axes = [
    { t: "Population covered", d: "Who is entitled. Move from selected groups toward everyone." },
    { t: "Services covered", d: "Which package. Move from a narrow list toward comprehensive PHC plus needed hospital care." },
    { t: "Cost covered", d: "What share is prepaid. Move away from OOPE toward pooling (NHA 2022-23: OOPE still 43.4% of THE)." },
  ];
  axes.forEach((a, i) => {
    const y = 180 + i * 360;
    roundRect(ctx, 760, y, 560, 320, 16, WHITE, PRIMARY, 2);
    ctx.fillStyle = PRIMARY;
    ctx.font = "700 24px Sans";
    ctx.fillText(a.t, 790, y + 55);
    wrapText(ctx, a.d, 790, y + 110, 500, 34, "22px Sans", BODY, 5);
  });
};

